CREATE TABLE IF NOT EXISTS structured_content (id TEXT PRIMARY KEY,content_type TEXT NOT NULL,title TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL,data_json TEXT NOT NULL,review_json TEXT NOT NULL DEFAULT '{}',created_at TEXT,updated_at TEXT);
CREATE TABLE IF NOT EXISTS product_feedback (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,product TEXT NOT NULL,entity_id TEXT NOT NULL,sentiment TEXT NOT NULL CHECK(sentiment IN ('yay','nay')),reason TEXT,context_json TEXT NOT NULL DEFAULT '{}',scope TEXT NOT NULL DEFAULT 'durable',expires_at TEXT,favourite INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,product,entity_id));
CREATE TABLE IF NOT EXISTS assessments (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'draft',answers TEXT,outcome TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
